// manifest.json: content script with world: MAIN, run_at: document_start
// MAIN world script runs in page origin (https://www.youtube.com) → has cookies + origin
const res = await fetch('/youtubei/v1/player', { method: 'POST', body: JSON.stringify(payload) });
const data = await res.json(); // 200 OK — page context present
window.postMessage({ type: '__YT_DETECTED_SUBTITLES', tracks, videoId }, '*');
// ISOLATED content-script listens → chrome.runtime.sendMessage → background SW

